const CACHE_NAME="bitcaster-pwa-cache-v1",URLS_TO_CACHE=["/pwa/","/static/pwa/style.css","/static/pwa/app.js","/static/pwa/images/name.svg"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(URLS_TO_CACHE)))}),self.addEventListener("activate",e=>{const t=[CACHE_NAME];e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(-1===t.indexOf(e))return caches.delete(e)}))))}),self.addEventListener("fetch",s=>{s.respondWith(caches.match(s.request).then(e=>{return e||(e=s.request.clone(),fetch(e).then(e=>{if(e&&200===e.status&&"basic"===e.type){const t=e.clone();caches.open(CACHE_NAME).then(e=>{e.put(s.request,t)})}return e}))}))});
